def rules(items):
    return '<dl class="refs rules">' + "".join(f"<dt>{md(a)}</dt><dd>{md(b)}</dd>" for a, b in items) + "</dl>"

RULE_PICK = ["STOP", "CHECK", "SEARCH", "ASK", "TRUST YOUR GUT"]
def situation(n, text):
    return f'<div class="sit"><p><b>{n}.</b> {md(text)}</p>{pick(["Best rule:"] + RULE_PICK)}</div>'

